import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not isinstance(r_script_path, str) or not isinstance(output_path, str):
        raise TypeError("Invalid input type for file paths")
    if not isinstance(duration, int):
        raise TypeError("Invalid input type for duration")
    if not os.path.exists(r_script_path):
        raise OSError("R script path does not exist")
    subprocess.Popen(['Rscript', r_script_path], shell=True)
    start_time = time.time()
    while time.time() - start_time < duration:
        if glob.glob(output_path):
            return True, 'File generated successfully within the specified duration.'
        time.sleep(0.1)
    return False, 'File not generated within the specified duration.'

import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    try:
        network = IPv4Network(ip_range, strict=False)
    except ValueError:
        raise ValueError("Invalid IP range")
    results = {}
    for ip in network:
        try:
            subprocess.run(['ping', '-c', '1', '-W', '1', str(ip)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, shell=True, check=True)
            results[str(ip)] = True
        except subprocess.CalledProcessError:
            results[str(ip)] = False
    return results

import subprocess
import platform
import time
def task_func(url):
    if not isinstance(url, str):
        raise TypeError("Invalid URL type")
    elif url == "":
        raise ValueError("URL cannot be empty")
    system = platform.system()
    if system == "Windows":
        process = subprocess.Popen(['start', url], shell=True)
    elif system == "Darwin":
        process = subprocess.Popen(['open', url], shell=True)
    else:
        process = subprocess.Popen(['xdg-open', url], shell=True)
    time.sleep(1)
    return process.poll()

import subprocess
import os
import random
def task_func(directory, file_list):
    if not os.path.isdir(directory):
        raise OSError("Invalid directory")
    if not file_list:
        return None
    selected_file = random.choice(file_list)
    file_path = os.path.join(directory, selected_file)
    if not os.path.isfile(file_path):
        raise OSError("File does not exist")
    process = subprocess.Popen(file_path, shell=True)
    return process.poll()

