import subprocess
# Constants
PYTHON_VERSION = '3.8'
PATH_TO_APPEND = '/path/to/whatever'
def task_func(python_version=PYTHON_VERSION, path_to_append=PATH_TO_APPEND):
    if not isinstance(python_version, str) or not isinstance(path_to_append, str):
        raise TypeError("Invalid input type")
    try:
        result = subprocess.run([f'python{python_version}', '--version'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
        if result.returncode != 0:
            raise OSError(f"Failed to switch to Python {python_version}")
    except Exception as e:
        raise OSError(f"Error occurred: {e}")
    if path_to_append not in sys.path:
        sys.path.append(path_to_append)
    return python_version

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("Invalid script path type")
    elif script_path == "" or not os.path.exists(script_path):
        raise OSError("Invalid script path")
    else:
        process = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    start_time = time.time()
    cpu_usage = 0
    memory_usage = 0

    try:
        while process.poll() is None:
            if time.time() - start_time > timeout:
                process.terminate()
                break
            proc = psutil.Process(process.pid)
            cpu_usage += proc.cpu_percent(interval=0.1)
            memory_usage += proc.memory_info().rss
            time.sleep(0.1)
    except psutil.NoSuchProcess:
        pass

    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}
